        callbacks,
        states: states
            .iter()
            .copied()
            .chain(tracked.iter().map(|(_, _, state)| *state))
            .collect(),
        overlay_count: states.len(),
        tracked: tracked.iter().map(|(target, _, _)| *target).collect(),
    })
}

fn bind(
    lua: &Lua,
    callback: &Function,
    actors: &[&Table],
    indices: &FxHashMap<usize, usize>,
