//! Paired real scene input/native actor execution and exact state traces.
use deadsync_song_lua::*;
use std::{hint::black_box, path::Path, sync::Arc};
#[path = "../../../tests/support/song_lua_metrics.rs"]
mod metrics;
type Kind = SongLuaOverlayKind<(), (), deadlib_present::actors::TextAttribute>;

#[cfg(windows)]
fn pin() {
    #[link(name = "kernel32")]
    unsafe extern "system" {
        fn GetCurrentThread() -> *mut std::ffi::c_void;
        fn SetThreadAffinityMask(thread: *mut std::ffi::c_void, mask: usize) -> usize;
    }
    // SAFETY: changes only this disposable benchmark worker's affinity.
    assert_ne!(
        unsafe { SetThreadAffinityMask(GetCurrentThread(), 1 << 2) },
        0
    );
}
#[cfg(not(windows))]
fn pin() {}

fn load(path: &Path) -> SongLuaLiveScene {
    let mut context = SongLuaCompileContext::new(path.parent().unwrap(), "actor input benchmark");
    context.live = true;
    context.music_length_seconds = 1.0;
    let mut compiled = compile_song_lua_layers_with_default_host(
        &[path],
        0,
        &context,
        SongLuaNoteskinResolver::default(),
        |_: &Path, _: &Path, _: &Path| Ok(Arc::<[()]>::from([])),
        |_: &()| None,
        |_: &SongLuaCompileContext, _: &str| None::<(Kind, SongLuaOverlayState)>,
    )
    .unwrap();
    compiled[0].live_scene.take().unwrap()
}

fn tracked(
    rows: impl Iterator<Item = (SongLuaTrackedActorTarget, SongLuaOverlayState)>,
) -> Vec<(usize, usize, SongLuaOverlayState)> {
    rows.map(|(target, state)| {
        use SongLuaTrackedActorTarget::*;
        let (kind, index) = match target {
            Player(p) => (0, p),
            PlayerJudgment(p) => (1, p),
            PlayerCombo(p) => (2, p),
            SongForeground => (3, 0),
            ScreenLayer(p) => (4, p),
        };
        (kind, index, state)
    })
    .collect()
}

fn event(index: usize) -> SongLuaInputEvent<'static> {
    SongLuaInputEvent {
        player: if index % 4 == 0 {
            None
        } else {
            Some(index % 2)
        },
        controller: Some(0),
        button: ["Left", "Right", "Other"][index % 3],
        game_button: ["Left", "Right", "Other"][index % 3],
        kind: [
            SongLuaInputType::FirstPress,
            SongLuaInputType::Repeat,
            SongLuaInputType::Release,
        ][index % 3],
        device: "InputDevice_Key",
        device_button: "DeviceButton_left",
        level: [-0.0, 0.25, 0.5, 1.0, f32::from_bits(0x7fc0_1234)][index % 5],
        z: index as i32 - 30,
        down: index % 4 < 2,
        ago: -0.0,
        is_joystick: false,
        is_mouse: false,
    }
}

fn main() {
    pin();
    let out = std::env::args().nth(1).expect("actor_input REPORT");
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let path = std::env::args()
        .nth(2)
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| root.join("tests/fixtures/actor-input.lua"));
    let mut live = load(&path);
    let mut native = live
        .compile_actor_inputs()
        .expect("visibility input lowering");
    let mut trace = Vec::new();
    for index in 0..60 {
        let input = event(index);
        let (handled, output) = live.input(&input).unwrap();
        assert!(output.errors.is_empty());
        let mut actions = Vec::new();
        assert_eq!(
            native.input_with_actions(&input, |action| actions.push(action)),
            handled
        );
        assert_eq!(native.states(), live.states());
        assert_eq!(
            tracked(native.tracked_states()),
            tracked(live.tracked_states())
        );
        trace.push(serde_json::json!({"handled":handled,"actions":format!("{actions:?}"),
            "states":format!("{:?}",native.states()),"tracked":format!("{:?}",tracked(native.tracked_states()))}));
    }
    let memory = serde_json::json!({"native_payload_bytes":native.retained_bytes(),
        "retained_lua_allocator_bytes":live.lua_memory_bytes(),
        "scope":"native owned input code, all overlay/tracked states and target identities; allocator/Arc bookkeeping excluded"});
    let mut rows = Vec::new();
    for sample in 0..10 {
        for current in [sample % 2 == 0, sample % 2 != 0] {
            let measure = metrics::Measurement::start();
            let mut digest = 0u64;
            for _ in 0..128 {
                for index in 0..60 {
                    let input = event(index);
                    let handled = if current {
                        native.input(black_box(&input))
                    } else {
                        live.input(black_box(&input)).unwrap().0
                    };
                    digest = digest.wrapping_mul(31).wrapping_add(u64::from(handled));
                }
            }
            let mut row = measure.finish();
            black_box(digest);
            if sample == 0 {
                continue;
            }
            row["workload"] = "actor_input_runtime".into();
            row["current"] = current.into();
            row["sample"] = sample.into();
            row["operations"] = (128 * 60).into();
            rows.push(row);
        }
    }
    for sample in 0..10 {
        let measure = metrics::Measurement::start();
        for _ in 0..128 {
            black_box(live.compile_actor_inputs().unwrap());
        }
        let mut row = measure.finish();
        if sample == 0 {
            continue;
        }
        row["workload"] = "actor_input_snapshot_prepare".into();
        row["operations"] = 128.into();
        row["sample"] = sample.into();
        rows.push(row);
    }
    // A Lua finalizer can run only when the actual loading VM closes. The
    // marker is rooted globally and never captured by the input callbacks.
    let marker =
        std::env::temp_dir().join(format!("deadsync-input-vm-drop-{}.txt", std::process::id()));
    let directory = tempfile::tempdir().unwrap();
    let file = directory.path().join("input.lua");
    let source = format!(
        "local proxy=newproxy(true); getmetatable(proxy).__gc=function() local f=assert(io.open([[{}]],'w'));f:write('closed');f:close() end; _G.input_drop_marker=proxy;\n{}",
        marker.to_string_lossy().replace('\\', "/"),
        std::fs::read_to_string(&path).unwrap()
    );
    std::fs::write(&file, source).unwrap();
    let scene = load(&file);
    let mut detached = scene.compile_actor_inputs().unwrap();
    if marker.exists() {
        std::fs::remove_file(&marker).unwrap();
    }
    assert!(!marker.exists());
    drop(scene);
    assert_eq!(std::fs::read_to_string(&marker).unwrap(), "closed");
    std::fs::remove_file(&marker).unwrap();
    for index in 0..60 {
        assert_eq!(
            detached.input(&event(index)),
            trace[index]["handled"].as_bool().unwrap()
        );
    }
    std::fs::write(out,serde_json::to_vec_pretty(&serde_json::json!({"rows":rows,"trace":trace,
        "retained_memory":memory,"loading_vm_destroyed":true,
        "validation":"Exact real-scene Lua/native actions and complete actor states over 60 inputs; native interaction runs after loading VM finalizer. Other scene lifecycle remains Lua. No pixel claim."})).unwrap()).unwrap();
}

measured_frame_reference_source:
//! Frozen frame construction from 94dd65ca1; only private enum-name access is adapted.
use crate::input::{SongLuaInputEvent,SongLuaInputType};
use mlua::program::Datum;
use smallvec::SmallVec;
fn kind_name(kind:SongLuaInputType)->&'static str {match kind {
 SongLuaInputType::FirstPress=>"InputEventType_FirstPress",
 SongLuaInputType::Repeat=>"InputEventType_Repeat",
 SongLuaInputType::Release=>"InputEventType_Release",
}}
pub(crate) struct Frame {
    controller: Option<SmallVec<[u8; 64]>>,
    player: Option<SmallVec<[u8; 64]>>,
}

impl Frame {
    pub fn new(input: &SongLuaInputEvent<'_>) -> Self {
        fn name(prefix: &[u8], index: Option<usize>) -> Option<SmallVec<[u8; 64]>> {
            index.map(|index| {
                let mut bytes = SmallVec::from_slice(prefix);
                let mut number = itoa::Buffer::new();
                bytes.extend_from_slice(number.format(index + 1).as_bytes());
                bytes
            })
        }
        Self {
            controller: name(b"GameController_", input.controller),
            player: name(b"PlayerNumber_P", input.player),
        }
    }

    pub fn values<'a>(&'a self, input: &'a SongLuaInputEvent<'_>) -> [Datum<'a>; 13] {
        [
            Datum::Bytes(input.button.as_bytes()),
            Datum::Bytes(input.game_button.as_bytes()),
            Datum::Bytes(kind_name(input.kind).as_bytes()),
            self.controller.as_deref().map_or(Datum::Nil, Datum::Bytes),
            self.player.as_deref().map_or(Datum::Nil, Datum::Bytes),
            Datum::Bytes(input.device.as_bytes()),
            Datum::Bytes(input.device_button.as_bytes()),
            Datum::Number(f64::from(input.level)),
            Datum::Number(f64::from(input.z)),
            Datum::Boolean(input.down),
            Datum::Number(input.ago),
            Datum::Boolean(input.is_joystick),
            Datum::Boolean(input.is_mouse),
        ]
    }
}

measured_program_tests_source:
#![cfg(feature = "lua51")]
use mlua::program::{self, Action, Binding, Bindings, Cell, Datum, Field, FieldValue, Parameter, Types};
use mlua::{Function, Lua, Table, Value};
use std::sync::{
    Arc, Mutex,
    atomic::{AtomicBool, Ordering},
};

struct Dropped(Arc<AtomicBool>);
impl Drop for Dropped {
    fn drop(&mut self) {
        self.0.store(true, Ordering::SeqCst);
    }
}

fn input(name: &str, slot: usize, types: Types) -> Field {
    Field {
        object: 0,
        name: name.as_bytes().into(),
        value: FieldValue::Value(Binding::Input { slot, types }),
    }
}
fn property(object: u32, name: &str, cell: usize) -> Field {
    Field {
        object,
        name: name.as_bytes().into(),
        value: FieldValue::Value(Binding::Cell(cell)),
    }
}
fn visible() -> Field {
    Field {
        object: 1,
        name: b"visible".as_slice().into(),
        value: FieldValue::Action(Action {
            tag: 7,
            parameters: vec![Parameter::Object(1), Parameter::Type(Types::BOOLEAN)],
            result: Some(Binding::Object(1)),
        }),
    }
}

#[derive(Debug, PartialEq)]
struct Row {
    handled: bool,
    held: bool,
    count: u64,
    actions: Vec<bool>,
}

#[test]
fn grouped_callbacks_share_actual_cells_and_survive_loading_vm_destruction() {
    let dropped = Arc::new(AtomicBool::new(false));
    let (mut group, expected) = {
        let lua = Lua::new();
        lua.set_app_data(Dropped(dropped.clone()));
        let actions = Arc::new(Mutex::new(Vec::new()));
        let actor = lua.create_table().unwrap();
        actor.set("visible", lua.create_function({
            let actor = actor.clone();
            let actions = actions.clone();
            move |_, (_, value): (Table, bool)| { actions.lock().unwrap().push(value); Ok(actor.clone()) }
        }).unwrap()).unwrap();
        let factory: Function = lua.load(r#"return function(actor)
            local state={held=false,count=-0.0}
            local alias=state
            return function(e)
                if e.button=='Right' then state.held=not state.held;actor:visible(state.held) end
                return false
            end,function(e)
                if e.type=='Release' then alias.count=alias.count+1;alias.held=false;actor:visible(false) end
                return alias.held
            end,state
        end"#).eval().unwrap();
        let (first, second, shared): (Function, Function, Table) = factory.call(actor.clone()).unwrap();
        let mut bindings = Bindings {
            arguments: vec![Binding::Object(0)],
            cells: vec![Cell::Boolean(false),Cell::Number(-0.0)],
            fields: vec![input("button",0,Types::BYTES),input("type",1,Types::BYTES),
                property(2,"held",0),property(2,"count",1),visible()],
            ..Bindings::default()
        };
        let mut programs = Vec::new();
        for callback in [&first,&second] {
            bindings.upvalues.clear();
            callback.for_each_upvalue_as::<mlua::InspectionValue>(|_,_,value| {
                let mlua::InspectionValue::Table(table)=value else { panic!("table capture"); };
                let object=if table.to_pointer()==actor.to_pointer() {1} else {
                    assert_eq!(table.to_pointer(),shared.to_pointer());2
                };
                bindings.upvalues.push(Binding::Object(object));Ok(())
            }).unwrap();
            programs.push(program::compile(callback,&bindings).unwrap());
        }
        let group=program::Group::new(programs).unwrap();
        let mut expected=Vec::new();
        for index in 0..24 {
            let event=lua.create_table().unwrap();
            event.set("button",if index%3==0 {"Left"}else{"Right"}).unwrap();
            event.set("type",if index%4==0 {"Release"}else{"Repeat"}).unwrap();
            let a=first.call::<Value>(event.clone()).unwrap();
            let b=second.call::<Value>(event).unwrap();
            expected.push((!matches!(a,Value::Nil|Value::Boolean(false)),!matches!(b,Value::Nil|Value::Boolean(false)),
                shared.get::<bool>("held").unwrap(),shared.get::<f64>("count").unwrap().to_bits(),
                std::mem::take(&mut *actions.lock().unwrap())));
        }
        (group,expected)
    };
    assert!(dropped.load(Ordering::SeqCst));
    assert_eq!(group.cell(1),Some(Datum::Number(-0.0)));
    for (index,(a,b,held,count,expected_actions)) in expected.into_iter().enumerate() {
        let inputs=[Datum::Bytes(if index%3==0 {b"Left"}else{b"Right"}),
            Datum::Bytes(if index%4==0 {b"Release"}else{b"Repeat"})];
        let mut actions=Vec::new();
        let mut run=|which|group.run(which,&inputs,|tag,args| {
            assert_eq!(tag,7);
            let Some(Datum::Boolean(value))=args.get(1)else{panic!("boolean action")};
            actions.push(value);
        }).unwrap().unwrap().is_truthy();
        assert_eq!(run(0),a);assert_eq!(run(1),b);
        assert_eq!(actions,expected_actions);
        assert_eq!(group.cell(0),Some(Datum::Boolean(held)));
        let Some(Datum::Number(value))=group.cell(1)else{panic!("number cell")};
        assert_eq!(value.to_bits(),count);
    }
    assert!(group.run(2,&[],|_,_|panic!("invalid index has no effects")).is_none());
}

#[test]
fn groups_check_cell_layout_bits_and_clear_scratch_between_programs() {
    let lua=Lua::new();
    let callback:Function=lua.load("local n=0;return function()return n end").eval().unwrap();
    let compile=|cell|program::compile(&callback,&Bindings{upvalues:vec![Binding::Cell(0)],cells:vec![cell],..Bindings::default()}).unwrap();
    assert!(program::Group::new(vec![compile(Cell::Number(-0.0)),compile(Cell::Number(0.0))]).is_err());
    assert!(program::Group::new(vec![compile(Cell::Boolean(false)),compile(Cell::Number(0.0))]).is_err());
    let bits=0x7ff8_0000_0000_1234;
    let group=program::Group::new(vec![compile(Cell::Number(f64::from_bits(bits))),compile(Cell::Number(f64::from_bits(bits)))]).unwrap();
    let Some(Datum::Number(value))=group.cell(0)else{panic!("number cell")};assert_eq!(value.to_bits(),bits);
    let a:Function=lua.load("return function()local a,b,c,d,e,f,g=1,2,3,4,5,6,7;return g end").eval().unwrap();
    let b:Function=lua.load("return function()local a;return a end").eval().unwrap();
    let mut group=program::Group::new(vec![program::compile(&a,&Bindings::default()).unwrap(),program::compile(&b,&Bindings::default()).unwrap()]).unwrap();
    for _ in 0..10 {
        assert_eq!(group.run(0,&[],|_,_|{}).unwrap().unwrap(),Datum::Number(7.0));
        assert_eq!(group.run(1,&[],|_,_|{}).unwrap().unwrap(),Datum::Nil);
    }
}

#[test]
fn real_branching_inputs_actions_and_aliased_state_survive_vm_destruction() {
    let dropped = Arc::new(AtomicBool::new(false));
    let sequence = [
        ("Left", "FirstPress"),
        ("Right", "FirstPress"),
        ("Right", "Repeat"),
        ("Right", "Release"),
        ("Right", "FirstPress"),
        ("Left", "Repeat"),
        ("Right", "Repeat"),
        ("Right", "FirstPress"),
        ("Right", "Release"),
        ("Right", "Release"),
    ];
    let (mut machine, expected) = {
        let lua = Lua::new();
        lua.set_app_data(Dropped(dropped.clone()));
        let trace = Arc::new(Mutex::new(Vec::new()));
        let actor = lua.create_table().unwrap();
        actor
            .set(
                "visible",
                lua.create_function({
                    let trace = trace.clone();
                    let actor = actor.clone();
                    move |_, (_, value): (Table, bool)| {
                        trace.lock().unwrap().push(value);
                        Ok(actor.clone())
                    }
                })
                .unwrap(),
            )
            .unwrap();
        let factory = lua
            .load(
                r#"return function(actor)
            local shared={held=false,count=0}
            local alias=shared
            return function(e)
                if e.button=='Right' then
                    if e.type=='Release' then shared.held=false
                    else shared.held=not alias.held end
                    shared.count=alias.count+1
                    actor:visible(shared.held)
                    return shared.count==2 or e.type=='Release'
                end
                return false
            end,shared
        end"#,
            )
            .eval::<Function>()
            .unwrap();
        let (callback, shared): (Function, Table) = factory.call(actor).unwrap();
        let mut bindings = Bindings {
            arguments: vec![Binding::Object(0)],
            cells: vec![Cell::Boolean(false), Cell::Number(0.0)],
            fields: vec![
                input("button", 0, Types::BYTES),
                input("type", 1, Types::BYTES),
                property(2, "held", 0),
                property(2, "count", 1),
                visible(),
            ],
            ..Bindings::default()
        };
        callback
            .for_each_upvalue(|_, name, _| {
                bindings.upvalues.push(Binding::Object(match name {
                    b"actor" => 1,
                    b"shared" | b"alias" => 2,
                    _ => panic!("unexpected capture"),
                }));
                Ok(())
            })
            .unwrap();
        let program = program::compile(&callback, &bindings).unwrap();
        let mut expected = Vec::new();
        for (button, kind) in sequence {
            let event = lua.create_table().unwrap();
            event.set("button", button).unwrap();
            event.set("type", kind).unwrap();
            let value = callback.call::<Value>(event).unwrap();
            expected.push(Row {
                handled: !matches!(value, Value::Nil | Value::Boolean(false)),
                held: shared.get("held").unwrap(),
                count: shared.get::<f64>("count").unwrap().to_bits(),
                actions: std::mem::take(&mut *trace.lock().unwrap()),
            });
        }
        (program.machine(), expected)
    };
    assert!(
        dropped.load(Ordering::SeqCst),
        "compiled interaction must release its loading VM"
    );
    for ((button, kind), expected) in sequence.into_iter().zip(expected) {
        let mut actions = Vec::new();
        let inputs = [Datum::Bytes(button.as_bytes()), Datum::Bytes(kind.as_bytes())];
        let handled = machine
            .run(&inputs, |tag, args| {
                assert_eq!(tag, 7);
                assert_eq!(args.len(), 2);
                assert_eq!(args.get(0), Some(Datum::Object(1)));
                let Some(Datum::Boolean(value)) = args.get(1) else {
                    panic!("typed action")
                };
                actions.push(value);
            })
            .unwrap()
            .is_truthy();
        let Some(Datum::Boolean(held)) = machine.cell(0) else {
            panic!("boolean cell")
        };
        let Some(Datum::Number(count)) = machine.cell(1) else {
            panic!("number cell")
        };
        assert_eq!(
            Row {
                handled,
                held,
                count: count.to_bits(),
                actions
            },
            expected
        );
    }
}

#[test]
fn primitive_truthiness_short_circuit_and_byte_strings_match_lua() {
    let lua = Lua::new();
    for body in [
        "return e.value or 'fallback'",
        "return e.value and true or false",
        "return not e.value",
        "if e.value == 'abc' then return 7 else return 0 end",
        "return e.value == '\\255\\0'",
        "return e.value ~= false",
    ] {
        let callback: Function = lua.load(format!("return function(e) {body} end")).eval().unwrap();
        let bindings = Bindings {
            arguments: vec![Binding::Object(0)],
            fields: vec![input(
                "value",
                0,
                Types::NIL | Types::BOOLEAN | Types::NUMBER | Types::BYTES,
            )],
            ..Bindings::default()
        };
        let mut machine = program::compile(&callback, &bindings).unwrap().machine();
        for input in [
            Datum::Nil,
            Datum::Boolean(false),
            Datum::Boolean(true),
            Datum::Number(0.0),
            Datum::Number(-0.0),
            Datum::Number(f64::NAN),
            Datum::Bytes(b""),
            Datum::Bytes(b"abc"),
            Datum::Bytes(&[255, 0]),
        ] {
            let event = lua.create_table().unwrap();
            match input {
                Datum::Nil => {}
                Datum::Boolean(v) => event.set("value", v).unwrap(),
                Datum::Number(v) => event.set("value", v).unwrap(),
                Datum::Bytes(v) => event.set("value", lua.create_string(v).unwrap()).unwrap(),
                _ => unreachable!(),
            }
            let expected = callback.call::<Value>(event).unwrap();
            let inputs = [input];
            let actual = machine.run(&inputs, |_, _| panic!("no host action")).unwrap();
            match (expected, actual) {
                (Value::Nil, Datum::Nil) => {}
                (Value::Boolean(a), Datum::Boolean(b)) => assert_eq!(a, b),
                (Value::Integer(a), Datum::Number(b)) => assert_eq!(a as f64, b),
                (Value::Number(a), Datum::Number(b)) => assert_eq!(a.to_bits(), b.to_bits()),
                (Value::String(a), Datum::Bytes(b)) => assert_eq!(a.as_bytes().as_ref(), b),
                other => panic!("different result: {body}: {other:?}"),
            }
        }
    }
}

#[test]
fn scalar_cells_preserve_number_bits_and_are_independent_per_machine() {
    let lua = Lua::new();
    let factory: Function = lua
        .load("return function(n) return function(e) n=n+e.delta; return -n end end")
        .eval()
        .unwrap();
    for initial in [-0.0, 0.0, 1.5, f64::from_bits(0x7ff8_0000_0000_1234)] {
        let callback: Function = factory.call(initial).unwrap();
        let bindings = Bindings {
            arguments: vec![Binding::Object(0)],
            upvalues: vec![Binding::Cell(0)],
            cells: vec![Cell::Number(initial)],
            fields: vec![input("delta", 0, Types::NUMBER)],
            ..Bindings::default()
        };
        let program = program::compile(&callback, &bindings).unwrap();
        let mut machine = program.machine();
        let untouched = program.machine();
        for delta in [-0.0, 0.0, 2.25, -0.5] {
            let event = lua.create_table().unwrap();
            event.set("delta", delta).unwrap();
            let expected = callback.call::<f64>(event).unwrap();
            let inputs = [Datum::Number(delta)];
            let Datum::Number(actual) = machine.run(&inputs, |_, _| panic!("no action")).unwrap() else {
                panic!("number result")
            };
            assert_eq!(actual.to_bits(), expected.to_bits());
        }
        let Some(Datum::Number(n)) = untouched.cell(0) else {
            panic!("number cell")
        };
        assert_eq!(n.to_bits(), initial.to_bits());
    }
}

